-- Read-only published-content probe using an ephemeral synthetic auth claim.
-- No Auth identity, student/session row, entitlement or provider request is created.
begin read only; select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true); with q as (select s.subject_key,c.topic_code,t.unit_number,v.stimulus_image_path from app.content_item_cells c join app.content_item_versions v on v.id=c.content_item_version_id join app.content_items ci on ci.id=c.content_item_id join app.exam_pack_versions epv on epv.id=ci.exam_pack_version_id join app.exam_packs ep on ep.id=epv.exam_pack_id join app.subjects s on s.id=ep.subject_id join app.taxonomy_topics t on t.taxonomy_source_version=c.taxonomy_source_version and t.topic_code=c.topic_code where c.validation_decision_id='68ccbdae-0349-5ba8-bbdd-27ecee4a27bc'),g as(select q.*,public.get_topic_point_guides(replace(subject_key,'-','_'),unit_number,topic_code) as guides from q),checked as(select g.*,exists(select 1 from jsonb_array_elements(coalesce(guides->'reference','[]'::jsonb)) r where coalesce(r->>'id',r->>'referenceEntryId') is not null and nullif(btrim(r->>'body'),'') is not null) usable_reference from g) select subject_key,count(*) as newly_tagged,count(*) filter(where usable_reference) as with_usable_reference,count(*) filter(where not usable_reference) as still_missing_reference,count(*) filter(where stimulus_image_path is not null) as with_question_image from checked group by subject_key order by subject_key; rollback;
